    # Now count missing values
    missing_counts = {col: 0 for col in header[3:]}
    for row in reader:
        for i, col in enumerate(header[3:]):
            if i < len(row):
                if row[i] == '':
                    missing_counts[col] += 1

    print(f"Missing counts: {missing_counts}")
